observation.command:
cd /workspace && node --input-type=module -e "
import { buildProfileEnv } from '/workspace/scripts/ops/runtime/profile-env.ts';
const e = buildProfileEnv('local-builder', { rootDir: '/workspace' });
console.log('STUDIO_JOB_WORKER_DB_USER=', e.STUDIO_JOB_WORKER_DB_USER);
console.log('STUDIO_JOB_WORKER_DB_PASSWORD set=', Boolean(e.STUDIO_JOB_WORKER_DB_PASSWORD));
console.log('POSTGRES_HOST=', e.POSTGRES_HOST, 'PORT=', e.POSTGRES_PORT);
"
echo "=== running server proc env (find app server pid = the one with cwd app root) ==="
for pid in $(ps -eo pid,args | awk '/[r]un-executor.js/{print $1}'); do
  echo "run-executor pid=$pid cwd=$(readlink /proc/$pid/cwd 2>/dev/null)"
done
# The actual node server: child of run-executor
RPID=$(ps -eo pid,ppid,args | awk '/[r]un-executor.js/{print $1}' | head -1)
CHILD=$(ps -eo pid,ppid | awk -v p=$RPID '$2==p{print $1}' | head -1)
echo "app server pid=$CHILD cwd=$(readlink /proc/$CHILD/cwd 2>/dev/null)"
tr '\0' '\n' < /proc/$CHILD/environ 2>/dev/null | grep -E 'STUDIO_JOB_WORKER|POSTGRES_HOST|POSTGRES_PORT' | sed 's/PASSWORD=.*/PASSWORD=<set>/'
